use std::path::Path;

fn is_safe_path(base: &Path, target: &Path) -> bool {
    if let Ok(resolved) = target.canonicalize() {
        return resolved.starts_with(base);
    }
    false
}

fn main() {
    let base_dir = Path::new("/data");
    let target_path = Path::new("/data/../etc/passwd");
    assert!(!is_safe_path(base_dir, target_path), "Path traversal detected!");
}

