use std::path::Path;

fn is_safe_path(base: &Path, input: &str) -> bool {
    let full_path = base.join(input);
    full_path.starts_with(base)
}

fn main() {
    let base_dir = Path::new("/data");
    let input_path = "../etc/passwd";
    assert!(!is_safe_path(base_dir, input_path), "Path traversal detected!");
}
